public class Solution {
    public static int findMaxIndex(int[] arr) {
        // CONTRACT: index of the FIRST occurrence of the maximum;
        // arr.length >= 1. Currently returns the last occurrence.
        int best = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] >= arr[best]) {
                best = i;
            }
        }
        return best;
    }
}

